import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { checkout, formatBaht } from '../api/backend';
import { useAuth } from '../auth/AuthContext';

export default function Checkout() {
  const { session } = useAuth();
  const navigate = useNavigate();
  const [address, setAddress] = useState('');
  const [card, setCard] = useState({ number: '4242 4242 4242 4242', expiry: '12/30', cvc: '123' });
  const [error, setError] = useState(null);
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const data = await checkout(session.token, { address, card });
      setResult(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  if (result) {
    return (
      <div className="mx-auto max-w-md px-4 py-12 text-center">
        <h1 className="text-xl font-semibold text-green-700">ชำระเงินสำเร็จ (จำลอง)</h1>
        <p className="mt-2 text-slate-600">หมายเลขคำสั่งซื้อ #{result.orderId}</p>
        <p className="mt-1 text-xl font-bold text-red-600">{formatBaht(result.totalSatang)}</p>
        <button onClick={() => navigate('/')} className="mt-6 rounded-md bg-red-600 px-4 py-2 text-white">
          กลับหน้าแรก
        </button>
      </div>
    );
  }

  const input = 'w-full rounded-md border border-slate-300 px-3 py-2 focus:border-red-500 focus:outline-none';

  return (
    <div className="mx-auto max-w-md px-4 py-8">
      <h1 className="text-xl font-semibold text-slate-800">ชำระเงิน</h1>
      <p className="mt-1 text-sm text-slate-500">บัตรทดสอบ: 4242 4242 4242 4242 (ระบบนี้เป็นการจำลอง ไม่มีการหักเงินจริง)</p>
      <form onSubmit={submit} className="mt-6 space-y-4 rounded-lg bg-white p-6 shadow-sm">
        <textarea className={input} rows={3} placeholder="ที่อยู่จัดส่ง" value={address}
                  onChange={(e) => setAddress(e.target.value)} required />
        <input className={input} placeholder="เลขบัตร" value={card.number}
               onChange={(e) => setCard({ ...card, number: e.target.value })} required />
        <div className="grid grid-cols-2 gap-4">
          <input className={input} placeholder="MM/YY" value={card.expiry}
                 onChange={(e) => setCard({ ...card, expiry: e.target.value })} />
          <input className={input} placeholder="CVC" value={card.cvc}
                 onChange={(e) => setCard({ ...card, cvc: e.target.value })} required />
        </div>
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button type="submit" disabled={busy}
                className="w-full rounded-md bg-red-600 py-2 font-semibold text-white disabled:bg-slate-300">
          {busy ? 'กำลังดำเนินการ...' : 'ยืนยันการชำระเงิน'}
        </button>
      </form>
    </div>
  );
}
